target.css:
:root {
  --ink: #26352d;
  --paper: #fffdf5;
  --line: #cbd8c2;
  --mint: #dcefd8;
  --green: #39724c;
}

.battery-card {
  width: 440px;
  box-sizing: border-box;
  padding: 16px;
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 14px;
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: center;
  gap: 12px;
}

.dial {
  display: grid;
  width: 46px;
  height: 46px;
  place-items: center;
  background: var(--mint);
  border: 1px solid var(--line);
  border-radius: 50%;
  font-size: 24px;
}

.eyebrow {
  margin: 0 0 3px;
  color: var(--green);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.7px;
}

h1 {
  margin: 0;
  font-size: 21px;
  line-height: 1.1;
}

footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 14px;
  padding-top: 10px;
  border-top: 1px solid var(--line);
  font-size: 13px;
}

strong {
  padding: 4px 8px;
  background: var(--mint);
  border-radius: 999px;
  color: var(--green);
  font-size: 11px;
  letter-spacing: 0.5px;
}
